contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);

        uint prePot = c.pot(); if (__ESBMC_reverted()) return;
        address bank = c.bank(); if (__ESBMC_reverted()) return;
        uint preBankBal = bank.balance;

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint postPot = c.pot(); if (__ESBMC_reverted()) return;
        uint postBankBal = bank.balance;

        assert(prePot == 0 || (postPot == 0 && postBankBal == preBankBal + 1));
    }

    receive() external payable {}
}

